// Устройство задано здесь: iPhone WebKit 390×844 (как при проверке 02.11); проект iphone по умолчанию 375.
import { test, expect, devices } from '@playwright/test';
import { DOCS, PARENT_B, expectDocOpen, visibleText } from './legal-docs.helpers';

test.use({
  browserName: 'webkit',
  viewport: { width: 390, height: 844 },
  isMobile: true,
  hasTouch: true,
  deviceScaleFactor: 3,
  userAgent: devices['iPhone 13'].userAgent,
  storageState: PARENT_B,
});

test.describe('Юридические документы — iPhone 390', () => {
  test('iPhone 390: оба документа под входом, без горизонтальной прокрутки, RTL @iphone @prod-safe #d7fe2c', async ({ page }) => {
    for (const doc of ['terms', 'privacy'] as const) {
      await page.goto(DOCS[doc].url);
      await expectDocOpen(page, doc);

      const scrollWidth = await page.evaluate(() => document.documentElement.scrollWidth);
      expect(scrollWidth, `${doc}: нет горизонтальной прокрутки`).toBe(390);

      const direction = await visibleText(page, DOCS[doc].title).evaluate((el) => getComputedStyle(el).direction);
      expect(direction, `${doc}: заголовок RTL`).toBe('rtl');
    }
  });
});
